const rawData = [
  {"id":"node1"},
  {"id":"node2"},
  {"id":"node3"},
  {"id":"node4"},
  {"id":"node5"},
  {"id":"node6"},
  {"id":"line-default","source":"node1","target":"node2"},
  {"id":"line-active","source":"node1","target":"node3","states":["active"]},
  {"id":"line-selected","source":"node1","target":"node4","states":["selected"]},
  {"id":"line-highlight","source":"node1","target":"node5","states":["highlight"]}
];

const nodes = rawData.filter(item => !item.source).map(item => ({
  id: item.id,
  data: { label: item.id }
}));

const edges = rawData.filter(item => item.source).map(item => ({
  id: item.id,
  source: item.source,
  target: item.target,
  states: item.states || []
}));

const graph = new Graph({
  container: 'container',
  autoFit: 'view',
  data: { nodes, edges },

  node: {
    type: 'rect',
    style: {
      size: [120, 40],
      radius: 4,
      fill: '#f0f5ff',
      stroke: '#adc6ff',
      lineWidth: 1,
      labelText: (d) => d.data.label,
      labelPlacement: 'center',
      labelFill: '#333',
      ports: [
        { key: 'left', placement: 'left', r: 3, fill: '#adc6ff', stroke: '#adc6ff' },
        { key: 'right', placement: 'right', r: 3, fill: '#adc6ff', stroke: '#adc6ff' }
      ]
    }
  },

  edge: {
    type: 'cubic-horizontal',
    style: {
      stroke: '#999',
      lineWidth: 1.5,
      endArrow: true,
      sourcePort: 'right',
      targetPort: 'left'
    },
    state: {
      selected: {
        stroke: '#1890ff',
        lineWidth: 3,
        endArrow: { fill: '#1890ff', stroke: '#1890ff' }
      },
      active: {
        stroke: '#fa8c16',
        lineWidth: 2,
        endArrow: { fill: '#fa8c16', stroke: '#fa8c16' }
      },
      highlight: {
        stroke: '#ff4d4f',
        lineWidth: 2,
        lineDash: [5, 5],
        endArrow: { fill: '#ff4d4f', stroke: '#ff4d4f' }
      }
    }
  },

  layout: {
    type: 'dagre',
    rankdir: 'LR',
    ranksep: 80,
    nodesep: 40,
    controlPoints: true
  },

  behaviors: ['drag-canvas', 'zoom-canvas', 'click-select']
});

graph.render();

