import { Graph } from '@antv/g6';

// 生成 16 个节点和 15 条边，按蛇形布局排列
const nodes = [];
const edges = [];
const cols = 4;
const rowHeight = 80;
const colWidth = 100;
const startX = 50;
const startY = 50;

for (let i = 0; i < 16; i++) {
  const row = Math.floor(i / cols);
  const col = i % cols;

  // 蛇形排列：偶数行从左到右，奇数行从右到左
  let x;
  if (row % 2 === 0) {
    x = startX + col * colWidth;
  } else {
    x = startX + (cols - 1 - col) * colWidth;
  }
  const y = startY + row * rowHeight;

  nodes.push({
    id: `${i}`,
    style: {
      x: x,
      y: y,
    },
    data: {
      label: `${i}`,
    },
  });

  // 生成 15 条边，连接相邻节点形成蛇形路径
  if (i < 15) {
    edges.push({
      source: `${i}`,
      target: `${i + 1}`,
    });
  }
}

