    graph.setElementState(nodeId, 'selected');
  } else {
    if (selectedNode !== nodeId) {
      const edgeId = `edge-${selectedNode}-${nodeId}-${Date.now()}`;
      graph.addEdgeData([
        {
          id: edgeId,
          source: selectedNode,
          target: nodeId,
          style: {
            stroke: 'red',
            lineWidth: 2,
            endArrow: true,
          },
        },
      ]);
      graph.draw();
    }
    graph.setElementState(selectedNode, []);
    selectedNode = null;
  }
});

