const rawNodes = [
  {"id":"0","data":{"cluster":"A"}},
  {"id":"1","data":{"cluster":"A"}},
  {"id":"2","data":{"cluster":"A"}},
  {"id":"3","data":{"cluster":"A"}},
  {"id":"4","data":{"cluster":"A"}},
  {"id":"5","data":{"cluster":"A"}},
  {"id":"6","data":{"cluster":"B"}},
  {"id":"7","data":{"cluster":"B"}},
  {"id":"8","data":{"cluster":"B"}},
  {"id":"9","data":{"cluster":"B"}}
];

// 自定义双层布局算法实现
const width = 800;
const height = 600;
const centerX = width / 2;
const layerGap = height / 3;

// 按聚类分组
const clusterANodes = rawNodes.filter(n => n.data.cluster === 'A');
const clusterBNodes = rawNodes.filter(n => n.data.cluster === 'B');

// 为每个节点计算坐标位置：A聚类在上层，B聚类在下层
const nodes = rawNodes.map((node) => {
  const isClusterA = node.data.cluster === 'A';
  const group = isClusterA ? clusterANodes : clusterBNodes;
  const indexInGroup = group.findIndex(n => n.id === node.id);
  const groupSize = group.length;

  // 在层内水平均匀分布，留出边距
  const spacing = width / (groupSize + 1);
  const x = spacing * (indexInGroup + 1);

  // 上层（A）在 1/3 高度，下层（B）在 2/3 高度
  const y = isClusterA ? layerGap : layerGap * 2;

  return {
    ...node,
    style: {
      x,
      y,
    }
  };
});

// 构建边关系：包含聚类内部连接和跨聚类连接
const edges = [
  // Cluster A 内部连接（上层）
  { source: '0', target: '1', data: { type: 'intra' } },
  { source: '1', target: '2', data: { type: 'intra' } },
  { source: '2', target: '3', data: { type: 'intra' } },
  { source: '3', target: '4', data: { type: 'intra' } },
  { source: '4', target: '5', data: { type: 'intra' } },
  { source: '0', target: '3', data: { type: 'intra' } },
  { source: '1', target: '4', data: { type: 'intra' } },

  // Cluster B 内部连接（下层）
  { source: '6', target: '7', data: { type: 'intra' } },
  { source: '7', target: '8', data: { type: 'intra' } },
  { source: '8', target: '9', data: { type: 'intra' } },
  { source: '6', target: '9', data: { type: 'intra' } },

  // 跨聚类连接（层间）
  { source: '2', target: '7', data: { type: 'inter' } },
  { source: '3', target: '8', data: { type: 'inter' } },
  { source: '5', target: '6', data: { type: 'inter' } },
  { source: '0', target: '9', data: { type: 'inter' } },
];

const graph = new Graph({
  container: container,
  width,
  height,
  data: {
    nodes,
    edges,
  },
  node: {
    type: 'circle',
    style: {
      size: 45,
      // 根据聚类设置不同颜色
      fill: (d) => d.data.cluster === 'A' ? '#1783FF' : '#FA8C16',
      stroke: (d) => d.data.cluster === 'A' ? '#0958D9' : '#D46B08',
      lineWidth: 3,
      labelText: (d) => `${d.id}(${d.data.cluster})`,
      labelPlacement: 'center',
      labelFill: '#fff',
      labelFontSize: 12,
      labelFontWeight: 'bold',
      // 添加阴影效果增强层次感
      shadowColor: (d) => d.data.cluster === 'A' ? 'rgba(23,131,255,0.4)' : 'rgba(250,140,22,0.4)',
      shadowBlur: 10,
      shadowOffsetX: 2,
      shadowOffsetY: 2,
    },
  },
  edge: {
    type: 'cubic-vertical', // 使用垂直曲线边，更适合上下层连接
    style: {
      lineWidth: 2,
      // 层内连接和层间连接使用不同样式
      stroke: (d) => d.data?.type === 'inter' ? '#BFBFBF' : '#595959',
      lineDash: (d) => d.data?.type === 'inter' ? [4, 4] : undefined,
      opacity: (d) => d.data?.type === 'inter' ? 0.6 : 0.8,
      endArrow: true,
      endArrowSize: 8,
    },
  },
  behaviors: [
    'drag-canvas',
    'zoom-canvas',
    'drag-element',
    'hover-activate',
  ],
});

graph.render();

